    css: "/* From Uiverse.io by KSAplay - Tags: button */\nbutton {\n  background-color: #0050ec;\n  color: white;\n  font-size: 16px;\n  font-weight: bold;\n  padding: 15px 20px;\n  border-radius: 2em;\n  cursor: pointer;\n  transition: 0.1s ease;\n  border-width: 0;\n  box-shadow: 1px 5px 0 0 #0e285d;\n}\n\nbutton:hover {\n  transform: translateY(-4px);\n  box-shadow: 1px 9px 0 0 #0e285d;\n}\n\nbutton:active {\n  transform: translateY(4px);\n  box-shadow: 0px 0px 0 0 #0e285d;\n}",
