    html: "<button class=\"btn\">\n        Hover me\n    </button>",
    css: "/* From Uiverse.io by Kemboi-Dun - Tags: button */\n.btn {\n  font-size: 17px;\n  background: transparent;\n  border: none;\n  padding: 1em 1.5em;\n  color: #f8f8f8;\n  text-transform: uppercase;\n  position: relative;\n  transition: .5s ease;\n  cursor: pointer;\n}\n\n.btn::before {\n  content: '';\n  position: absolute;\n  right: 0;\n  top: 0;\n  height: 2px;\n  width: 0;\n  background-color: #f8f8f8;\n  transition: .5s ease;\n}\n\n.btn:hover {\n  color: #181818;\n  transition-delay: .5s;\n}\n\n.btn:hover::before {\n  width: 100%;\n}\n\n.btn::after {\n  content: '';\n  position: absolute;\n  left: 0;\n  bottom: 0;\n  height: 0;\n  width: 100%;\n  background-color: #f8f8f8;\n  transition: .4s ease;\n  z-index: -1;\n}\n\n.btn:hover::after {\n  height: 100%;\n  transition-delay: 0.4s;\n}",
