    css: "/* From Uiverse.io by Madflows - Tags: button, download */\n.button {\n  position: relative;\n  overflow: hidden;\n  height: 3rem;\n  padding: 0 2rem;\n  border-radius: 1.5rem;\n  background: #3d3a4e;\n  background-size: 400%;\n  color: #fff;\n  border: none;\n}\n\n.button:hover::before {\n  transform: scaleX(1);\n}\n\n.button-content {\n  position: relative;\n  z-index: 1;\n}\n\n.button::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  transform: scaleX(0);\n  transform-origin: 0 50%;\n  width: 100%;\n  height: inherit;\n  border-radius: inherit;\n  background: linear-gradient(\n    82.3deg,\n    rgba(150, 93, 233, 1) 10.8%,\n    rgba(99, 88, 238, 1) 94.3%\n  );\n  transition: all 0.475s;\n}",
