    html: "<button class=\"btn-hover\">HOVER ME</button>",
    css: "/* From Uiverse.io by Nayzerftn - Tags: button, hover, active */\n.btn-hover {\n  position: relative;\n  display: inline-block;\n  padding: 15px 30px;\n  font-size: 18px;\n  font-weight: bold;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  color: #ffffff;\n  background-color: #4b4b4b;\n  border: none;\n  outline: none;\n  overflow: hidden;\n  cursor: pointer;\n  transition: all 0.3s ease-out;\n}\n\n.btn-hover:hover {\n  background-color: #522ba7;\n}\n\n.btn-hover::before {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%) scale(0);\n  width: 15px;\n  height: 15px;\n  border-radius: 50%;\n  background-color: #ffffff;\n  opacity: 0.8;\n  transition: all 0.5s ease-out;\n}\n\n.btn-hover:hover::before {\n  transform: translate(-50%, -50%) scale(20);\n  opacity: 0;\n}",
