    css: "/* From Uiverse.io by NomNomcats  - Tags: simple, flashy, button, hover */\n.button10 {\n  display: inline-block;\n  transition: all 0.3s ease;\n  position: relative;\n  overflow: hidden;\n  z-index: 1;\n  color: #ffffff;\n  padding: 0.8em 2em;\n  cursor: pointer;\n  font-size: 16px;\n  border-radius: 0.5em;\n  background: #000;\n  border: 2px solid #00ffea;\n  box-shadow: 0 0 20px rgba(0, 255, 234, 0.5);\n}\n\n.button10:active {\n  color: #ffffff;\n  box-shadow: inset 0 0 10px rgba(0, 255, 234, 0.7);\n}\n\n.button10:before,\n.button10:after {\n  content: \"\";\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  top: 0;\n  left: 0;\n  background: rgba(0, 255, 234, 0.2);\n  z-index: -1;\n  transform: scale(0);\n  transition: transform 0.5s;\n  border-radius: inherit;\n}\n\n.button10:before {\n  transition-delay: 0s;\n}\n\n.button10:after {\n  transition-delay: 0.25s;\n}\n\n.button10:hover:before,\n.button10:hover:after {\n  transform: scale(1.2);\n}",
