    css: "/* From Uiverse.io by Remon125 - Tags: button, smooth button */\nbutton {\n  padding: 15px 60px;\n  background: transparent;\n  border: 2px solid #6528F7;\n  font-size: 15px;\n  font-weight: bold;\n  color: #ffffff;\n  border-radius: 6px;\n  cursor: pointer;\n  position: relative;\n  display: flex;\n  overflow: hidden;\n  transition: all 0.5s;\n  text-transform: uppercase;\n}\n\nbutton span {\n  transition: all 0.5s;\n  z-index: -1;\n}\n\nbutton::after,\nbutton::before {\n  content: \"\";\n  position: absolute;\n  width: 0;\n  height: 100%;\n  background: #6528F7;\n  top: 0;\n  transform: skewX(35deg);\n  transition: all 0.5s;\n  z-index: -1;\n}\n\nbutton::after {\n  left: -20px;\n}\n\nbutton::before {\n  right: -20px;\n}\n\nbutton:hover::after {\n  width: 50%;\n  left: 0;\n}\n\nbutton:hover::before {\n  width: 50%;\n  right: 0;\n}",
