    css: "/* From Uiverse.io by SujitAdroja - Tags: button */\n.btn {\n  color: purple;\n  text-transform: uppercase;\n  text-decoration: none;\n  border: 2px solid purple;\n  padding: 10px 20px;\n  font-size: 17px;\n  font-weight: bold;\n  background: transparent;\n  position: relative;\n  transition: all 1s;\n  overflow: hidden;\n}\n\n.btn:hover {\n  color: white;\n}\n\n.btn::before {\n  content: '';\n  position: absolute;\n  height: 100%;\n  width: 0%;\n  top: 0;\n  left: -40px;\n  transform: skewX(45deg);\n  background-color: purple;\n  z-index: -1;\n  transition: all 1s;\n}\n\n.btn:hover::before {\n  width: 160%;\n}",
