    css: "/* From Uiverse.io by gharsh11032000 - Tags: button, hover effect */\n.button {\n  position: relative;\n  font-size: 24px;\n  font-weight: 600;\n  padding: 15px 30px;\n  color: #cfef00;\n  background-color: transparent;\n  border: 2px solid #cfef00;\n  border-radius: 10px;\n  cursor: pointer;\n  transition: all 0.4s cubic-bezier(0.23, 1, 0.320, 1);\n  overflow: hidden;\n}\n\n.button::before {\n  content: '';\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  background: #cfef00;\n  top: 0%;\n  left: -100%;\n  scale: 1;\n  border-radius: inherit;\n  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);\n}\n\n.button span {\n  transition: all 0.7s;\n  position: relative;\n  overflow: hidden;\n}\n\n.button span::before {\n  position: absolute;\n  content: 'Hover!';\n  top: 0;\n  left: 0;\n  color: #212121;\n  width: 0;\n  overflow: hidden;\n}\n\n.button:hover span::before {\n  width: 100%;\n  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);\n  transition-delay: 0.4s;\n}\n\n.button:hover::before {\n  scale: 1;\n  top: 0%;\n  left: 0%;\n}\n\n.button:hover {\n  border-color: transparent;\n}\n\n.button:active {\n  scale: 0.9;\n}",
