    css: "/* From Uiverse.io by mayurd8862 - Tags: button, cool btn */\n.button {\n  padding: 0.6em 1.3em;\n  font-weight: 900;\n  font-size: 18px;\n  background: linear-gradient(to right, rgb(231, 71, 132), \n  rgb(0, 170, 255));\n  /* Gradient background */\n  border-radius: 10px;\n  border: none;\n  color: aliceblue;\n  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.8);\n  /* Text shadow effect */\n  box-shadow: 0 0 10px rgba(55, 0, 255, 0.5);\n  cursor: pointer;\n  transition: transform 0.3s ease, box-shadow 0.3s ease, color 0.3s ease;\n}\n\n.button:hover {\n  transform: scale(1.1);\n  box-shadow: 0 0 15px rgb(231, 71, 132);\n  color: white;\n}",
