    author: "212004ALJI",
    source: "galaxy",
    html: "<button>\n  INPUT\n</button>",
    css: "/* From Uiverse.io by 212004ALJI - Tags: button */\nbutton {\n  /* padding: 5px 10px; */\n  height: 50px;\n  width: 100px;\n  font-size: 20px;\n  position: relative;\n  border: navajowhite;\n  background-color: #222;\n  color: aliceblue;\n  z-index: 1;\n  overflow: hidden;\n  transition: all 0.3s;\n  box-shadow: 2px 2px 2px red;\n}\n\nbutton::before {\n  content: '';\n  height: 10px;\n  width: 30px;\n  position: absolute;\n  background-image: linear-gradient(45deg, salmon,red);\n  left: -10px;\n  top: 0;\n  z-index: -1;\n  transition: 0.3s ease-in-out;\n  border-radius: 5px;\n}\n\nbutton:hover::before {\n  height: 100px;\n  width: 100px;\n}\n\nbutton:hover {\n  border-radius: 5px;\n}",
