    css: "/* From Uiverse.io by JsGrisales - Tags: button */\nbutton {\n  min-height: 53px;\n  min-width: 166px;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  -ms-flex-pack: distribute;\n  justify-content: space-around;\n  position: relative;\n  cursor: pointer;\n  background: -webkit-gradient(linear, left top, right top, color-stop(-12.74%, rgba(110, 239, 255, .5)), color-stop(56.76%, rgba(106, 224, 255, .271)));\n  background: linear-gradient(90deg, rgba(110, 239, 255, .5) -12.74%, rgba(106, 224, 255, .271) 56.76%);\n  border: 2px solid #acf7ff;\n  color: #FFFFFF;\n  font-size: 18px;\n  font-weight: 600;\n}\n\nbutton:before {\n  content: \"\";\n  width: 4px;\n  height: 28px;\n  background: #19173b;\n  border: 2px solid #acf7ff;\n  -webkit-transform: rotate(-45deg);\n  -ms-transform: rotate(-45deg);\n  transform: rotate(-45deg);\n  position: absolute;\n  border-top: 0;\n  border-left: 0;\n  border-bottom: 0;\n  bottom: -7px;\n  left: 4px;\n  border-bottom-left-radius: 10px;\n  border-top-left-radius: 10px;\n}\n\nbutton:after {\n  content: \"\";\n  position: absolute;\n  left: -2px;\n  bottom: -2px;\n  border-top: 15px solid transparent;\n  border-left: 15px solid #fffcf7;\n}",
