    css: "/* From Uiverse.io by Madflows - Tags: button, animated */\n.button {\n  outline: none;\n  border: none;\n  height: 3.5em;\n  padding: 0 2.5rem;\n  border-radius: 0.375rem;\n  background: #4503dc;\n  color: #fff;\n  -webkit-box-shadow: 0 0.4rem 0 0 #3700b8;\n  box-shadow: 0 0.4rem 0 0 #3700b8;\n  letter-spacing: 1px;\n  -webkit-transition: all 0.3s;\n  transition: all 0.3s;\n  font-family: sans-serif;\n  font-weight: 700;\n}\n\n.button:active {\n  -webkit-transform: translateY(0.3rem);\n  -ms-transform: translateY(0.3rem);\n  transform: translateY(0.3rem);\n  -webkit-box-shadow: 0 0.2rem 0 0 #3700b8;\n  box-shadow: 0 0.2rem 0 0 #3700b8;\n}",
