    css: "/* From Uiverse.io by Rodrypaladin - Tags: simple, animation, purple, pink, button, click, css, click animation */\n.button {\n  margin: 0 10px;\n  padding: 10px 30px;\n  border: 5px solid #DF34DB;\n  border-radius: 22px;\n  font-size: 20px;\n  color: #DF34DB;\n  transition: transform 0.1s ease-in, all 0.08s ease-in;\n  box-shadow: 0 5px 0 #dd04d9;\n}\n\n.button:hover {\n  border-color: #ff00c8;\n  box-shadow: 0 5px 0 #ff00c8;\n}\n\n.button:active {\n  transform: translateY(5px);\n  box-shadow: 0 0 0 #DF34DB;\n}",
