    css: "/* From Uiverse.io by Webdevava - Tags: button */\nbutton {\n  background: #111;\n  border: none;\n  padding: 10px 14px;\n  border-radius: 6px;\n  color: #fff;\n  font-size: 30px;\n}\n\nbutton:hover {\n  border: 3px solid #fff;\n  transform: rotate3d(0, 1, 0.5, 360deg);\n  transition: 1.5s;\n}",
