    css: "/* From Uiverse.io by glisovic01 - Tags: button */\n.btn {\n  display: inline-block;\n  font-family: sans-serif;\n  font-weight: 600;\n  font-size: 16px;\n  color: #fff;\n  margin: 1rem auto;\n  padding: 0.7rem 2rem;\n  border-radius: 30em;\n  border-style: none;\n  position: relative;\n  z-index: 1;\n  overflow: hidden;\n  text-decoration: none;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  background-color: transparent;\n  box-shadow: 1px 1px 12px #000000;\n}\n\n.btn::before {\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  top: 0;\n  left: 0;\n  background-color: #fff;\n  transform: translateX(-101%);\n  transition: all .3s ease;\n  z-index: -1;\n}\n\n.btn:hover {\n  color: #272727;\n  transition: all .3s ease;\n}\n\n.btn:hover::before {\n  transform: translateX(0);\n}",
