    css: "/* From Uiverse.io by hannahyockel - Tags: button */\nbutton {\n display: flex;\n flex-direction: row;\n justify-content: center;\n align-items: center;\n padding: 15px 38px;\n border-radius: 16px;\n border: 1px solid transparent;\n color: #FFFFFF;\n background-color: #1DC9A0;\n font-size: 16px;\n letter-spacing: 1px;\n transition: all 0.15s linear;\n}\n\nbutton:hover {\n background-color: rgba(29, 201, 160, 0.08);\n border-color: #1DC9A0;\n color: #1DC9A0;\n transform: translateY(-5px) scale(1.05);\n}\n\nbutton:active {\n background-color: transparent;\n border-color: #1DC9A0;\n color: #1DC9A0;\n transform: translateY(5px) scale(0.95);\n}\n\nbutton:disabled {\n background-color: rgba(255, 255, 255, 0.16);\n color: #8E8E93;\n border-color: #8E8E93;\n}",
