    html: "<button>\n  <span>\n  Hover me\n  </span>\n</button>",
    css: "/* From Uiverse.io by iamriishav - Tags: button */\nbutton {\n  padding: 15px 30px;\n  border: none;\n  outline: none;\n  border-radius: 30px;\n  font-size: 1.5rem;\n  z-index: 1;\n  position: relative;\n  -webkit-box-shadow: 0 5px 15px rgba(33, 33, 33, .2);\n  box-shadow: 0 5px 15px rgba(33, 33, 33, .2);\n  overflow: hidden;\n  cursor: pointer;\n}\n\nbutton > span {\n  z-index: 2;\n}\n\nbutton::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  border-radius: 30px;\n  background-color: #212121;\n  z-index: -1;\n  overflow: hidden;\n  -webkit-transform: scaleX(0);\n  -ms-transform: scaleX(0);\n  transform: scaleX(0);\n  -webkit-transform-origin: left;\n  -ms-transform-origin: left;\n  transform-origin: left;\n  -webkit-transition: -webkit-transform 0.2s ease-in;\n  transition: -webkit-transform 0.2s ease-in;\n  transition: transform 0.2s ease-in;\n}\n\nbutton:hover {\n  color: #e8e8e8;\n}\n\nbutton:hover::before {\n  -webkit-transform: scaleX(1);\n  -ms-transform: scaleX(1);\n  transform: scaleX(1);\n  -webkit-transform-origin: left;\n  -ms-transform-origin: left;\n  transform-origin: left;\n}",
