    css: "/* From Uiverse.io by laminelawal - Tags: alert, button, 2d button */\n.frame {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 400px;\n  height: 400px;\n  margin-top: -200px;\n  margin-left: -200px;\n  border-radius: 2px;\n  box-shadow: 4px 8px 16px 0 rgba(0,0,0,0.1);\n  overflow: hidden;\n  background: #fff;\n  color: #333;\n  font-family: 'Open Sans', Helvetica, sans-serif;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n.center {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%,-50%);\n}\n\nbutton {\n  padding: 15px 15px;\n  border: none;\n  width: 170px;\n  height: 55px;\n  box-shadow: 15px 15px darkblue;\n  cursor: pointer;\n  transition: 0.5s ease;\n  background: lightgray;\n  font-size: 18px;\n  font-weight: bolder;\n  text-transform: uppercase;\n}\n\nbutton:hover {\n  box-shadow: -15px -15px lightgray;\n  transform: translate(15px, 15px);\n  background: darkblue;\n  color: white;\n}",
