    css: "/* From Uiverse.io by ossoboy - Tags: button */\nbutton {\n background-color: rgb(82, 163, 255);\n color: transparent;\n border: 0 none;\n padding: 15px 30px;\n text-decoration: none;\n display: inline-block;\n transition: background-color 300ms ease, color 300ms ease;\n font-size: 17px;\n position: relative;\n text-align: center;\n cursor: pointer;\n}\n\nbutton::before,\nbutton::after {\n content: attr(data-label);\n display: inline-block;\n position: absolute;\n transition: all 300ms ease;\n width: 100%;\n left: 0;\n top: 50%;\n color: white;\n}\n\nbutton::before {\n opacity: 0;\n transform: translateY(calc(-50% - 15px));\n}\n\nbutton::after {\n opacity: 1;\n transform: translateY(-50%);\n}\n\nbutton:hover {\n background-color: rgb(66, 133, 209);\n}\n\nbutton:hover::before {\n opacity: 1;\n transform: translateY(-50%);\n}\n\nbutton:hover::after {\n opacity: 0;\n transform: translateY(calc(-50% + 15px));\n}\n\nbutton:active {\n background-color: rgb(82, 163, 255);\n}",
