    css: "/* From Uiverse.io by vinodjangid07 - Tags: gradient, button, hover effect, gold, golden effect , subscribe, premium */\n.Btn {\n  width: 200px;\n  height: 40px;\n  border: none;\n  border-radius: 40px;\n  background: linear-gradient(to right,#bf953f,#fcf6ba,#b38728,#fbf5b7,#aa771c);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  font-size: 0.8em;\n  color: rgb(121, 103, 3);\n  font-weight: 600;\n  cursor: pointer;\n  position: relative;\n  z-index: 2;\n  transition-duration: 3s;\n  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.144);\n  background-size: 200% 200%;\n}\n\n.logoIcon path {\n  fill: rgb(121, 103, 3);\n}\n\n.Btn:hover {\n  transform: scale(0.95);\n  transition-duration: 3s;\n  animation: gradient 5s ease infinite;\n  background-position: right;\n}",
