    css: "/* From Uiverse.io by zjssun - Tags: button, neon */\nbutton {\n  padding: 10px 20px;\n  text-transform: uppercase;\n  border-radius: 8px;\n  font-size: 17px;\n  font-weight: 500;\n  color: #ffffff80;\n  text-shadow: none;\n  background: transparent;\n  box-shadow: transparent;\n  border: 1px solid #ffffff80;\n  transition: 0.5s ease;\n  user-select: none;\n}\n\n#btn:hover,:focus {\n  color: #ffffff;\n  background: #008cff;\n  border: 1px solid #008cff;\n  text-shadow: 0 0 5px #ffffff,\n              0 0 10px #ffffff,\n              0 0 20px #ffffff;\n  box-shadow: 0 0 5px #008cff,\n              0 0 20px #008cff,\n              0 0 50px #008cff,\n              0 0 100px #008cff;\n}",
